#!/usr/bin/env python3
"""Generate the working manuscript's table from the sealed holdout run."""
from pathlib import Path

from consumer_holdout import BASE, ROOT
from evaluate_consumer_pilot import load


def percent(value):
    return f"{100 * value:.1f}\\%"


def interval(values):
    return f"[{percent(values[0])}, {percent(values[1])}]"


def main():
    result = load(BASE / "runs/selfhosted-v1/results.json")
    col_names = ("Primary", "Alternate 1", "Alternate 2")
    table = [
        "% Generated by scripts/render_consumer_holdout.py",
        r"\begin{table*}[t]",
        r"\centering\small",
        rf"\caption{{Paired documented consumer coverage in the frozen frame of {result['denominator']} application repositories. "
        r"Zero documented hits include unresolved evidence. The final two columns bound gross turnover and signed "
        r"version-minus-name net coverage under incomplete evidence. Alternate rows substitute the other "
        r"additive-optimal version portfolios.}",
        r"\label{tab:consumer_holdout}",
        r"\setlength{\tabcolsep}{5pt}",
        r"\begin{tabular}{lrrrrrrcc}",
        r"\toprule",
        r"Comparison & Both & Name only & Version only & \shortstack{Neither\\documented} & \shortstack{Resolved\\pairs} & \shortstack{Documented\\turnover} "
        r"& \shortstack{Full-reference\\turnover} & \shortstack{Full-reference\\net}\\",
        r"\midrule",
    ]
    for i, name in enumerate(col_names, start=1):
        r = result["comparisons"][f"version_{i}"]
        c = r["documented_cells"]
        fields = [name, c["11"], c["10"], c["01"], c["00"], r["resolved_pairs"], percent(r["documented_turnover"]),
                  interval(r["complete_reference_turnover_bounds"]), interval(r["complete_reference_net_bounds"])]
        table.append(" & ".join(str(value) for value in fields) + r"\\")
    table += [r"\bottomrule", r"\end{tabular}", r"\end{table*}"]
    (ROOT / "manuscript_q1/tables/consumer_holdout_table.tex").write_text("\n".join(table) + "\n")


if __name__ == "__main__":
    main()
